function processPaymentTransaction(req, db) {
  if (!req.headers || !req.headers["x-signature"]) throw new Error("UNAUTHORIZED: missing cryptographic signature");
  const idempotencyKey = req.headers["idempotency-key"];
  if (!idempotencyKey) throw new Error("BAD_REQUEST: missing idempotency key");
  if (db.hasProcessed(idempotencyKey)) return { status: 200, message: "Duplicate transaction safely ignored" };
  if (!req.url.startsWith("https://")) throw new Error("SECURITY_VIOLATION: TLS 1.3 required");
  return db.commit(req.payload);
}
module.exports = { processPaymentTransaction };
